import { Component, Input, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { NgbActiveModal } from '@ng-bootstrap/ng-bootstrap';
import { ToastrService } from 'ngx-toastr';
import { DefinitionItem, DefinitionService } from 'src/app/_services/definition.service';

@Component({
  selector: 'app-add-reservationtype',
  templateUrl: './add-reservationtype.component.html',
  styleUrls: ['./add-reservationtype.component.css']
})
export class AddReservationtypeComponent implements OnInit {
  readonly resource = 'reservationtypes' as const;
  submitted = false;
  definitionForm: FormGroup;

  @Input() hammadde: DefinitionItem;

  constructor(
    private formBuilder: FormBuilder,
    private activeModal: NgbActiveModal,
    private hammaddeService: DefinitionService,
    private toastr: ToastrService
  ) {}

  ngOnInit() {
    this.definitionForm = this.formBuilder.group({
      name: ['', Validators.required],
      description: [''],
      price: [''],
      startPrice: [''],
      type: [1]
    });

    if (this.hammadde) {
      this.definitionForm.patchValue({
        name: this.hammadde.name,
        description: this.hammadde.description,
        price: this.hammadde.price,
        startPrice: this.hammadde.startPrice,
        type: this.hammadde.type
      });
    }
  }

  close() {
    this.activeModal.close();
  }

  save() {
    if (!this.definitionForm.valid) {
      this.definitionForm.markAllAsTouched();
      return;
    }

    this.submitted = true;
    const request = this.hammadde?.id
      ? this.hammaddeService.updateDefinition(this.resource, this.hammadde.id, { ...this.definitionForm.value, id: this.hammadde.id })
      : this.hammaddeService.createDefinition(this.resource, this.definitionForm.value);

    request.subscribe({
      next: () => {
        this.submitted = false;
        this.toastr.clear();
        this.toastr.success('', this.hammadde?.id ? 'KayÄ±t gÃ¼ncelleme baÅarÄ±lÄ±' : 'KayÄ±t baÅarÄ±lÄ±');
        this.activeModal.close(true);
      },
      error: () => {
        this.toastr.error('', this.hammadde?.id ? 'KayÄ±t gÃ¼ncelleme sÄ±rasÄ±nda hata oluÅtu' : 'KayÄ±t sÄ±rasÄ±nda hata oluÅtu');
        this.submitted = false;
      }
    });
  }
}
