import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { environment } from 'src/environments/environment';

export interface AdminSession {
    accessToken?: string;
    id?: number;
    role?: number;
    username?: string;
}

@Injectable({
    providedIn: 'root'
})
export class IdentityService {
    private readonly sessionStorageKey = 'currentUser';

    constructor(private http: HttpClient) {}

    dologin(value: { username: string; password: string }) {
        return this.http.post<AdminSession>(`${environment.apiUrl}admin/auth`, value);
    }

    storeSession(session: AdminSession, username?: string) {
        const normalizedSession: AdminSession = {
            ...session,
            username: username ?? session?.username ?? 'Admin'
        };

        localStorage.setItem(this.sessionStorageKey, JSON.stringify(normalizedSession));
    }

    getSession(): AdminSession | null {
        const sessionJson = localStorage.getItem(this.sessionStorageKey);

        if (!sessionJson) {
            return null;
        }

        try {
            return JSON.parse(sessionJson) as AdminSession;
        } catch {
            this.clearSession();
            return null;
        }
    }

    getAccessToken(): string | null {
        return this.getSession()?.accessToken ?? null;
    }

    isAuthenticated(): boolean {
        return !!this.getAccessToken();
    }

    clearSession() {
        localStorage.removeItem(this.sessionStorageKey);
    }

    doLogout() {
        this.clearSession();
        return Promise.resolve();
    }

    forgetPassword(value: any) {
        return this.http.post<any>(`${environment.apiUrl}identity/reset`, value);
    }

    changePassword(value: any) {
        return this.http.post<any>(`${environment.apiUrl}identity/changepassword`, value);
    }
}
