import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { environment } from 'src/environments/environment';

export type DefinitionResource = 'documenttypes' | 'licencetypes' | 'reservationtypes';

export interface DefinitionItem {
  id?: number;
  name: string;
  description?: string;
  price?: number;
  startPrice?: number;
  type?: number;
}

@Injectable({
  providedIn: 'root'
})
export class DefinitionService {
  private readonly baseUrl = `${environment.apiUrl}admin/definitions`;

  constructor(private http: HttpClient) { }

  getDefinitions(resource: DefinitionResource) {
    return this.http.get<DefinitionItem[]>(`${this.baseUrl}/${resource}`);
  }

  createDefinition(resource: DefinitionResource, model: DefinitionItem) {
    return this.http.post(`${this.baseUrl}/${resource}`, model);
  }

  updateDefinition(resource: DefinitionResource, id: number, model: DefinitionItem) {
    return this.http.put(`${this.baseUrl}/${resource}/${id}`, model);
  }

  deleteDefinition(resource: DefinitionResource, id: number) {
    return this.http.delete(`${this.baseUrl}/${resource}/${id}`);
  }
}
