import { RouterModule, Routes } from '@angular/router';
import { CustomerDetailComponent } from './customers/customer-detail/customer-detail.component';
import { CustomersComponent } from './customers/customers.component';
import { DashboardComponent } from './dashboard/dashboard.component';
import { DocumentTypeComponent } from './document-type/document-type.component';
import { DriverDetailComponent } from './drivers/driver-detail/driver-detail.component';
import { DriversComponent } from './drivers/drivers.component';
import { AuthGuard } from './_guards/auth.guard';
import { PrivateLayoutComponent } from './_layout/private-layout/private-layout.component';
import { PublicLayoutComponent } from './_layout/public-layout/public-layout.component';
import { LicenceTypeComponent } from './licence-type/licence-type.component';
import { LoginComponent } from './login';
import { PrivacyPolicyComponent } from './login/privacy-policy/privacy-policy.component';
import { TermsConditionComponent } from './login/terms-condition/terms-condition.component';
import { ReservationTypesComponent } from './reservation-types/reservation-types.component';
import { IncidentsComponent } from './incidents/incidents.component';
import { ReservationDetailComponent } from './reservations/reservation-detail/reservation-detail.component';
import { ReservationsComponent } from './reservations/reservations.component';
import { RideSettingsComponent } from './ride-settings/ride-settings.component';

const appRoutes: Routes = [
  { path: 'privacypolicy', component: PrivacyPolicyComponent },
  { path: 'termCondition', component: TermsConditionComponent },
  {
    path: '',
    component: PublicLayoutComponent,
    children: [
      { path: 'login', component: LoginComponent },
      { path: '', component: LoginComponent }
    ]
  },
  {
    path: '',
    component: PrivateLayoutComponent,
    children: [
      { path: 'logout', component: LoginComponent, canActivate: [AuthGuard] },
      { path: 'dashboard', component: DashboardComponent, canActivate: [AuthGuard] },
      { path: 'reservations', component: ReservationsComponent, canActivate: [AuthGuard] },
      { path: 'reservations/:id', component: ReservationDetailComponent, canActivate: [AuthGuard] },
      { path: 'incidents', component: IncidentsComponent, canActivate: [AuthGuard] },
      { path: 'drivers', component: DriversComponent, canActivate: [AuthGuard] },
      { path: 'drivers/:id', component: DriverDetailComponent, canActivate: [AuthGuard] },
      { path: 'customers', component: CustomersComponent, canActivate: [AuthGuard] },
      { path: 'customers/:id', component: CustomerDetailComponent, canActivate: [AuthGuard] },
      { path: 'documents', component: DocumentTypeComponent, canActivate: [AuthGuard] },
      { path: 'licences', component: LicenceTypeComponent, canActivate: [AuthGuard] },
      { path: 'reservationtypes', component: ReservationTypesComponent, canActivate: [AuthGuard] },
      { path: 'settings', component: RideSettingsComponent, canActivate: [AuthGuard] }
    ]
  },
  { path: '**', redirectTo: 'login' }
];

export const routing = RouterModule.forRoot(appRoutes, { scrollOffset: [0, 0], scrollPositionRestoration: 'top' });
