import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { environment } from 'src/environments/environment';

@Injectable({
  providedIn: 'root'
})
export class ReservationService {
  private readonly baseUrl = `${environment.apiUrl}admin/reservations`;

  constructor(private http: HttpClient) { }

  getReservations() {
    return this.http.get<any[]>(this.baseUrl);
  }

  getReservation(id: any) {
    return this.http.get<any>(`${this.baseUrl}/${id}`);
  }

  /// Sofor payinin iyzico havuzundan hesabina aktarilmasi icin onay verir.
  /// Onay surus tamamlaninca kendiliginden veriliyor; bu cagri, o adim yokken
  /// tahsil edilip havuzda kalmis odemeler ve onayi basarisiz olmus kayitlar icin.
  approvePayouts(id: any) {
    return this.http.post<any>(`${this.baseUrl}/${id}/approve`, {});
  }

  /// Tahsil edilmis odemeleri yolcuya geri verir.
  refundPayments(id: any) {
    return this.http.post<any>(`${this.baseUrl}/${id}/refund`, {});
  }

  getIncidents(status?: string, search?: string, reservationId?: any) {
    const params = new URLSearchParams();
    if (status) {
      params.set('status', status);
    }
    if (search) {
      params.set('search', search);
    }
    if (reservationId) {
      params.set('reservationId', reservationId);
    }

    const query = params.toString();
    return this.http.get<any[]>(`${environment.apiUrl}admin/incidents${query ? `?${query}` : ''}`);
  }

  updateIncident(id: any, model: any) {
    return this.http.put<any>(`${environment.apiUrl}admin/incidents/${id}`, model);
  }
}
