import { Component, Input, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { NgbActiveModal } from '@ng-bootstrap/ng-bootstrap';
import { ToastrService } from 'ngx-toastr';
import { DefinitionItem, DefinitionResource, DefinitionService } from 'src/app/_services/definition.service';

@Component({
  selector: 'app-simple-definition-modal',
  templateUrl: './simple-definition-modal.component.html',
  styleUrls: ['./simple-definition-modal.component.css']
})
export class SimpleDefinitionModalComponent implements OnInit {
  @Input() item?: DefinitionItem;
  @Input() resource!: DefinitionResource;
  @Input() title = 'Tanım';

  submitted = false;
  definitionForm!: FormGroup;

  constructor(
    private formBuilder: FormBuilder,
    private activeModal: NgbActiveModal,
    private definitionService: DefinitionService,
    private toastr: ToastrService
  ) {}

  ngOnInit() {
    this.definitionForm = this.formBuilder.group({
      name: [this.item?.name ?? '', Validators.required]
    });
  }

  close() {
    this.activeModal.close();
  }

  save() {
    if (!this.definitionForm.valid) {
      this.definitionForm.markAllAsTouched();
      return;
    }

    this.submitted = true;
    const request = this.item?.id
      ? this.definitionService.updateDefinition(this.resource, this.item.id, { ...this.definitionForm.value, id: this.item.id })
      : this.definitionService.createDefinition(this.resource, this.definitionForm.value);

    request.subscribe({
      next: () => {
        this.submitted = false;
        this.toastr.clear();
        this.toastr.success('', this.item?.id ? 'Kayıt güncellendi' : 'Kayıt eklendi');
        this.activeModal.close(true);
      },
      error: () => {
        this.submitted = false;
        this.toastr.error('', this.item?.id ? 'Kayıt güncellenemedi' : 'Kayıt eklenemedi');
      }
    });
  }
}
