import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { environment } from 'src/environments/environment';

@Injectable({
  providedIn: 'root'
})
export class DriverService {

constructor(private http:HttpClient) { }
getDrivers(){
  return this.http.get<any[]>(environment.apiUrl+"admin/drivers");
}

get(id:any){
  return this.http.get<any>(environment.apiUrl+"admin/drivers/"+id);
}
acceptDriver(id:any){
  return this.http.post<any>(environment.apiUrl+"admin/drivers/accept/"+id, {});
}

getDeposit(){
  return this.http.get<any>(environment.apiUrl+"admin/drivers/deposit");
}
}
