import { Component, OnInit } from '@angular/core';
import { NgbModal } from '@ng-bootstrap/ng-bootstrap';
import { BlockUI, NgBlockUI } from 'ng-block-ui';
import { ToastrService } from 'ngx-toastr';
import { DefinitionItem, DefinitionResource, DefinitionService } from '../_services/definition.service';
import { AddReservationtypeComponent } from './add-reservationtype/add-reservationtype.component';

@Component({
  selector: 'app-reservation-types',
  templateUrl: './reservation-types.component.html',
  styleUrls: ['./reservation-types.component.scss']
})
export class ReservationTypesComponent implements OnInit {
  readonly resource: DefinitionResource = 'reservationtypes';

  @BlockUI('changelog') blockUIChangelog: NgBlockUI;
  documents: DefinitionItem[];

  constructor(
    private definitionService: DefinitionService,
    private modal: NgbModal,
    private toastr: ToastrService
  ) {}

  ngOnInit() {
    this.loadDefinitions();
  }

  loadDefinitions() {
    this.definitionService.getDefinitions(this.resource).subscribe(res => {
      this.documents = res;
    });
  }

  reloadChangelog() {
    this.blockUIChangelog.start('Loading..');

    setTimeout(() => {
      this.blockUIChangelog.stop();
    }, 2500);
  }

  openSaveModal() {
    const modalref = this.modal.open(AddReservationtypeComponent, { size: 'lg' });
    modalref.result.then(() => this.loadDefinitions(), () => undefined);
  }

  openEditModal(data: DefinitionItem) {
    const modalref = this.modal.open(AddReservationtypeComponent, { size: 'xl' });
    modalref.componentInstance.hammadde = data;
    modalref.result.then(() => this.loadDefinitions(), () => undefined);
  }

  delete(id: number) {
    this.definitionService.deleteDefinition(this.resource, id).subscribe(() => {
      this.loadDefinitions();
      this.toastr.success('', 'KayÄ±t silindi');
    });
  }

  gettype(type) {
    if (type == 1) {
      return "Dakika Bazlı";
    } else if (type == 2) {
      return "Km Bazlı";
    } else if (type == 3) {
      return "Sabit Ücret";
    } else if (type == 4) {
      return "Şehir Dışı";
    } else {
      return "Bilinmiyor";
    }
  }
}
