import { Component, OnInit } from '@angular/core';
import { NgbModal } from '@ng-bootstrap/ng-bootstrap';
import { BlockUI, NgBlockUI } from 'ng-block-ui';
import { ToastrService } from 'ngx-toastr';
import { DefinitionItem, DefinitionResource, DefinitionService } from '../_services/definition.service';
import { SimpleDefinitionModalComponent } from '../shared/simple-definition-modal/simple-definition-modal.component';

@Component({
  selector: 'app-document-type',
  templateUrl: './document-type.component.html',
  styleUrls: ['./document-type.component.scss']
})
export class DocumentTypeComponent implements OnInit {
  readonly resource: DefinitionResource = 'documenttypes';
  readonly modalTitle = 'Döküman Türü';

  @BlockUI('changelog') blockUIChangelog: NgBlockUI;
  documents: DefinitionItem[];

  constructor(
    private definitionService: DefinitionService,
    private modal: NgbModal,
    private toastr: ToastrService
  ) {}

  ngOnInit() {
    this.loadDefinitions();
  }

  loadDefinitions() {
    this.definitionService.getDefinitions(this.resource).subscribe(res => {
      this.documents = res;
    });
  }

  reloadChangelog() {
    this.blockUIChangelog.start('Loading..');

    setTimeout(() => {
      this.blockUIChangelog.stop();
    }, 2500);
  }

  openSaveModal() {
    const modalref = this.modal.open(SimpleDefinitionModalComponent, { size: 'lg' });
    modalref.componentInstance.resource = this.resource;
    modalref.componentInstance.title = this.modalTitle;
    modalref.result.then(() => this.loadDefinitions(), () => undefined);
  }

  openEditModal(data: DefinitionItem) {
    const modalref = this.modal.open(SimpleDefinitionModalComponent, { size: 'lg' });
    modalref.componentInstance.item = data;
    modalref.componentInstance.resource = this.resource;
    modalref.componentInstance.title = this.modalTitle;
    modalref.result.then(() => this.loadDefinitions(), () => undefined);
  }

  delete(id: number) {
    this.definitionService.deleteDefinition(this.resource, id).subscribe(() => {
      this.loadDefinitions();
      this.toastr.success('', 'KayÄ±t silindi');
    });
  }
}
